"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[60681],{46057:e=>{e.exports=JSON.parse('{"product":"Connect","entries":[{"id":"2026-11-12-sms-test-program-us","date":"2026-11-12","products":["Connect"],"product":"Connect","channel":"SMS","changeType":"Added","title":"SMS Test Program (US) guide","excerpt":"Added a guide for prospective customers and partners who want to test SMS delivery to US mobile phones on the 8x8 CPaaS platform before signing up: how to opt in from your own mobile phone, what kinds of test messages you\'ll receive, and how to opt out.","hasArticle":true},{"id":"2026-10-27-sms-inbound-mms-media-urls","date":"2026-10-27","products":["Connect","APIs"],"product":"Connect","channel":"SMS","changeType":"Added","title":"Inbound MMS media on the inbound SMS webhook","excerpt":"When a user sends an MMS to one of your MMS-enabled US/Canada virtual numbers, the inbound SMS webhook (inboundmessagereceived) now includes a mediaUrls array with a link to each media file, alongside the message text in body. mediaUrls is omitted for plain SMS.","hasArticle":true},{"id":"2026-10-21-sms-mms-media-urls","date":"2026-10-21","products":["Connect","APIs"],"product":"Connect","channel":"SMS","changeType":"Added","title":"MMS media support on the Send SMS API","excerpt":"You can now send media (image, audio, video, etc.) along with an SMS as an MMS, by adding a mediaUrls field to your send request \u2014 up to 10 HTTPS URLs, each up to 4096 characters. MMS is currently supported for US/Canada destinations only; for other destinations mediaUrls is ignored and the message is sent as a plain S\u2026","hasArticle":true},{"id":"2026-10-16-whatsapp-button-reply-webhook-fields","date":"2026-10-16","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Changed","title":"Button replies in the inbound Messaging Apps webhook clarified","excerpt":"The inbound Messaging Apps webhook(/connect/docs/inbound-chatapps-message) page now explains how to tell which WhatsApp button a customer tapped, with sample payloads for both kinds of button.","hasArticle":true},{"id":"2026-10-13-whatsapp-direct-send","date":"2026-10-13","products":["Connect","APIs"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"WhatsApp Direct Send","excerpt":"A new guide documents Direct Send: you send utility message content directly, and WhatsApp matches it to an existing template or creates one for you. You don\'t need to create a template or wait for approval before the first send.","hasArticle":true},{"id":"2026-10-13-whatsapp-service-message-charging","date":"2026-10-13","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Changed","title":"WhatsApp pricing: service messages and in-window Utility templates now charged","excerpt":"The WhatsApp docs now reflect Meta\'s pricing change effective October 1, 2026. Two kinds of message that were free inside an open 24-hour Customer Service Window (CSW) are now charged per delivered message.","hasArticle":true},{"id":"2026-09-24-outboundcontent-on-sms-delivery-receipts","date":"2026-09-24","products":["Connect","APIs"],"product":"Connect","channel":"SMS","changeType":"Added","title":"outboundContent on SMS delivery receipts","excerpt":"SMS delivery receipts now document the outboundContent object \u2014 a structured copy of the original outbound message the receipt refers to. It lets you reconcile a delivery receipt with the exact content that was sent without keeping your own copy of the outbound payload.","hasArticle":true},{"id":"2026-09-23-whatsapp-business-calling-guides-rewritten","date":"2026-09-23","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Changed","title":"WhatsApp Business Calling guides rewritten","excerpt":"The four WhatsApp Business Calling guides (overview, user-initiated, business-initiated, and scenarios) have been rewritten to match how calling is delivered on 8x8.","hasArticle":true},{"id":"2026-09-07-whatsapp-business-app-coexistence","date":"2026-09-07","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"WhatsApp Business App Coexistence","excerpt":"A new guide documents Coexistence \u2014 connecting a phone number that\'s already active in the WhatsApp Business app to the WhatsApp Business Platform (Cloud API) through 8x8 Connect or the ChatApps API, so both keep working on the same number at once. Your team can keep answering 1:1 chats from the mobile app while 8x8 Co\u2026","hasArticle":true},{"id":"2026-09-02-callflows-client-request-and-batch-ids","date":"2026-09-02","products":["Connect","APIs"],"product":"Connect","channel":"Voice","changeType":"Added","title":"Correlation and batch IDs on the Callflows API","excerpt":"The Callflows API now accepts two optional top-level fields for tracking your own requests: clientRequestId and clientBatchId. Both are echoed back in the Voice Session Summary (VSS) webhook, so you can correlate a webhook back to the request that created it, or to the batch it belongs to, without keeping your own mapp\u2026","hasArticle":true},{"id":"2026-09-02-webhook-callback-urls-https","date":"2026-09-02","products":["Connect","APIs"],"product":"Connect","channel":"","changeType":"Changed","title":"Webhook and callback URL sample values updated to HTTPS","excerpt":"Sample URL values across the SMS and Business Messaging (Chat Apps) API documentation \u2014 webhook configuration, dlrCallbackUrl, delivery-receipt callback overrides, and rich-content URL fields \u2014 now use https://example.com instead of http://example.com, so the examples no longer read as an endorsement of plain HTTP for\u2026","hasArticle":true},{"id":"2026-09-01-viber-template-status-webhook","date":"2026-09-01","products":["Connect","APIs"],"product":"Connect","channel":"Viber","changeType":"Added","title":"Viber Template Status Webhook","excerpt":"You can now receive a Viber Template Status Webhook when Viber moderates a message template you registered, so your systems stay in sync without polling.","hasArticle":true},{"id":"2026-08-27-viber-get-delete-template-endpoints","date":"2026-08-27","products":["Connect","APIs"],"product":"Connect","channel":"Viber","changeType":"Added","title":"Get and Delete Viber template endpoints","excerpt":"You can now retrieve and delete Viber message templates via API, in addition to creating them.","hasArticle":true},{"id":"2026-08-19-outboundcontent-timing-corrected","date":"2026-08-19","products":["Connect","APIs"],"product":"Connect","channel":"","changeType":"Fixed","title":"outboundContent timing corrected on WhatsApp delivery receipts","excerpt":"The Delivery receipts for Outbound Messaging Apps(/connect/docs/delivery-receipts-for-outbound-chatapps) guide previously stated that the outboundContent object is attached to the receipt confirming delivery to the recipient (deliveredtorecipient). That was inaccurate.","hasArticle":true},{"id":"2026-08-13-viber-template-send-examples","date":"2026-08-13","products":["Connect","APIs"],"product":"Connect","channel":"Viber","changeType":"Added","title":"Viber template send examples in the Send message reference","excerpt":"The Send message API reference now includes worked request examples for sending Viber template messages, covering both template categories: transactional templates and OTP templates.","hasArticle":true},{"id":"2026-08-11-rcs-rich-card-media-height-optional","date":"2026-08-11","products":["Connect","APIs"],"product":"Connect","channel":"RCS","changeType":"Fixed","title":"RCS rich card media height documented as optional","excerpt":"The media.height field on RCS rich cards was documented as if a value were always required. It is now clarified as optional, defaulting to SHORT when omitted.","hasArticle":true},{"id":"2026-08-07-viber-message-templates","date":"2026-08-07","products":["Connect","APIs"],"product":"Connect","channel":"Viber","changeType":"Added","title":"Viber message templates","excerpt":"You can now create and manage Viber message templates \u2014 pre-approved message formats for transactional messages and OTPs, with dynamic {{parameter}} placeholders substituted at send time. Creating templates requires an admin role on the account.","hasArticle":true},{"id":"2026-08-05-rcs-attribution-corrected","date":"2026-08-05","products":["Connect"],"product":"Connect","channel":"RCS","changeType":"Fixed","title":"RCS attribution corrected","excerpt":"The RCS guide previously described Rich Communication Services as \\"a protocol developed by Google.\\" That was inaccurate, and it is now corrected.","hasArticle":true},{"id":"2026-08-04-templateid-in-direct-send-delivery-receipts","date":"2026-08-04","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"templateId in Direct Send delivery receipts","excerpt":"WhatsApp delivery receipts now include a templateId field for messages sent via the WhatsApp Direct Send API, so you can correlate a receipt back to the exact template that was delivered.","hasArticle":true},{"id":"2026-08-03-line-channel-documentation","date":"2026-08-03","products":["Connect"],"product":"Connect","channel":"LINE","changeType":"Added","title":"LINE channel documentation","excerpt":"The full LINE channel documentation is now published. LINE is the most popular chat app in Japan, Thailand, and Taiwan, and it reaches users through the same 8x8 Messaging Apps API and webhook envelope you already use for SMS, WhatsApp, Viber, and RCS.","hasArticle":true},{"id":"2026-07-28-verification-api-templatekey-parameter","date":"2026-07-28","products":["Connect","APIs"],"product":"Connect","channel":"Verification","changeType":"Changed","title":"Verification API templateKey parameter","excerpt":"The Verification API request now accepts a templateKey parameter, letting you select a pre-saved message template by its key instead of supplying the message content inline. The example values used across the Verification API documentation have also been standardised.","hasArticle":true},{"id":"2026-07-28-whatsapp-automatic-events-webhook","date":"2026-07-28","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"WhatsApp Automatic Events webhook","excerpt":"You can now receive WhatsApp Automatic Events webhooks \u2014 notifications sent when Meta detects a qualifying conversion event (a purchase or a lead) inside a WhatsApp thread that originated from a Click-to-WhatsApp ad. 8x8 forwards these detected events to your endpoint so you can feed conversion data into your own analy\u2026","hasArticle":true},{"id":"2026-07-21-business-scoped-user-ids-bsuid","date":"2026-07-21","products":["Connect","APIs"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"Business-Scoped User IDs (BSUID)","excerpt":"WhatsApp is rolling out optional usernames, which let people message a business without handing over their phone number. So that those users stay reachable, Meta gives every WhatsApp user a persistent Business-Scoped User ID (BSUID). 8x8 now surfaces the BSUID as user.channelUserId throughout the WhatsApp over 8x8 API.\u2026","hasArticle":true},{"id":"2026-07-21-outbound-context-on-outbound-api-v9","date":"2026-07-21","products":["Connect","APIs"],"product":"Connect","channel":"","changeType":"Changed","title":"Outbound context on Outbound API v9","excerpt":"Outbound Messaging Apps delivery receipts on version 9 now carry additional context about the message they refer to. A new outboundContent object gives you a structured, channel-normalized copy of the WhatsApp message that was delivered, so you can reconcile a delivery receipt with the exact content sent without keepin\u2026","hasArticle":true},{"id":"2026-07-16-whatsapp-request-call-info","date":"2026-07-16","products":["Connect","APIs"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"WhatsApp Request Call Info","excerpt":"You can now check a customer\'s WhatsApp call permission status before you place a business-initiated call. Meta requires customers to explicitly grant permission before a business can call them on WhatsApp, and the new Get Call Permission Status endpoint tells you whether that permission is in place, whether you are cu\u2026","hasArticle":true},{"id":"2026-07-07-chat-apps-inbound-and-outbound-messaging","date":"2026-07-07","products":["Connect","APIs"],"product":"Connect","channel":"","changeType":"Added","title":"Chat Apps inbound and outbound messaging","excerpt":"You can now follow end-to-end how-to documentation for sending and receiving Chat Apps messages on the 8x8 platform. The Chat Apps API lets you reach customers across supported channels \u2014 WhatsApp, Viber, RCS, LINE, and others \u2014 through a single message API, and receive their replies and delivery updates on the webhook\u2026","hasArticle":true}]}')}}]);